static void render_users(FILE *out, const user_t *us, size_t n) {
    fputs("<ul>", out);
    for (size_t i = 0; i < n; i++) {
        fputs("<li>", out);
        html_escape(out, us[i].name);          /* %s would NOT escape */
        fprintf(out, " (%zu)</li>", us[i].logins);
    }
    fputs("</ul>\n", out);
}
